import { useState, useSyncExternalStore } from "react";

/* Example dates count from when they appear. An app takes its dates from its data. */

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/** A fixed moment for server rendering, so the server and the browser write the same HTML. */
const reference = Date.UTC(2026, 0, 15, 12);

const subscribe = () => () => {
  // Whether the page has hydrated never changes back.
};

const useDemoClock = () => {
  // oxlint-disable-next-line react/hook-use-state -- the time is read once, when the example appears, and never replaced.
  const [appeared] = useState(() => Date.now());

  return useSyncExternalStore(
    subscribe,
    () => appeared,
    () => reference,
  );
};

export { DAY, HOUR, MINUTE, useDemoClock };

import { RelativeTime, RelativeTimeProvider } from "@/registry/erbium/ui/relative-time";
import { DAY, MINUTE, useDemoClock } from "../examples/use-demo-clock";

const formats = [
  { label: "Long", props: {} },
  { label: "Short", props: { formatStyle: "short" } },
  { label: "Narrow", props: { formatStyle: "narrow" } },
  { label: "Numbers only", props: { numeric: "always" } },
  { label: "Duration", props: { format: "duration" } },
] as const;

export default function RelativeTimeFormatsExample() {
  const now = useDemoClock();
  const dates = [now - 5 * MINUTE, now - DAY];

  return (
    <RelativeTimeProvider locale="en">
      <dl className="grid grid-cols-[auto_auto_auto] gap-x-8 gap-y-2 text-caption">
        {formats.map(({ label, props }) => (
          <div key={label} className="contents">
            <dt className="text-muted-foreground">{label}</dt>
            {dates.map((date) => (
              <dd key={date}>
                <RelativeTime date={date} {...props} />
              </dd>
            ))}
          </div>
        ))}
      </dl>
    </RelativeTimeProvider>
  );
}
